String workPage = tools.getPrimaryPage().getName();
org.json.simple.JSONObject oViewData;
String caseID;

if (tools.getParamValue("ruleType").equals("Rule-Obj-FlowAction"))
{
  // render the view as json
  oViewData = (org.json.simple.JSONObject)pega_uiengine_harness.pzAPICreateJsonForView(actionSection, workPage, false);
  caseID = myStepPage.getString(".pyID");
}
else 
{
  // render the harness as json
  oViewData = (org.json.simple.JSONObject)pega_uiengine_harness.pzAPICreateJsonForCreationPage(tools.getParamValue("ruleName"), workPage, false);
  oViewData = (org.json.simple.JSONObject)oViewData.get("creation_page");
  caseID = "creation of " + myStepPage.getClassName();
}

if (oViewData != null)
{
  // retrieve the fields of the view in a hashmap
  java.util.HashMap oFieldsMap = new java.util.HashMap();
  pega_api_pzserviceapi.pzGetViewFields(oViewData, oFieldsMap);

  if (pega_rules_utilities.getDataSystemSetting("Pega-API", "DebugPegaAPI").equalsIgnoreCase("true"))
  {
    oLog.infoForced("Fields of the section " + actionSection + ": " + oFieldsMap.entrySet());
  }

  // disable declaratives before validating the request body
  pega_wb_clipboardviewer.pzDisableDeclarativesOnCurrentThread(true);  

  if (pega_api_pzserviceapi.pzValidateViewFields(pageParam_ContentPage, oFieldsMap, caseID, actionSection, tools.getParamValue("ruleName")))
    // It all passed so we exit the activity
    nextBlock = "***";

  // re-enable declaratives
  pega_wb_clipboardviewer.pzDisableDeclarativesOnCurrentThread(false);  
}
else
  oLog.error("Attempt to retrieve JSON for " + tools.getParamValue("ruleType") + " " + tools.getParamValue("ruleName") + " failed.");
